mapper.select:
SELECT id, user_id, category_id, name, price, original_price, stock,
       status, view_count, condition_level, location, contact_method,
       create_time, update_time, create_by, update_by, del_flag, version,
       MATCH(name) AGAINST(#{keyword} IN NATURAL LANGUAGE MODE) AS relevance
FROM eo_product
WHERE MATCH(name) AGAINST(#{keyword} IN NATURAL LANGUAGE MODE)
  AND status = #{status}
  
      AND price >= #{minPrice}
  
  
      AND price <= #{maxPrice}
  
  
      AND condition_level = #{conditionLevel}
  
ORDER BY relevance DESC, create_time DESC

SELECT id, product_id, image_url, sort_order, is_main, create_time FROM eo_product_image WHERE product_id IN
#{id}
ORDER BY product_id, sort_order ASC

SELECT id, name, parent_id, level, icon, sort_order, status, create_time, update_time, create_by, update_by, del_flag FROM eo_category WHERE id IN
#{id}
AND del_flag = 0
